public class ArrayStack<T> implements IGenStack<T>{private final T[]data;private int size;public ArrayStack(T[]data){this.data=data;}public void push(T value)throws StackFullException{if(size==data.length)throw new StackFullException(size);data[size++]=value;}public T pop(){if(size==0)ArrayStack.<RuntimeException>raise(new StackEmptyException("empty"));return data[--size];}private static <E extends Throwable>void raise(Throwable x)throws E{throw (E)x;}}
